import{_ as a,c as s,o as n,b0 as l}from"./chunks/framework.Dmsv_Tiv.js";const h=JSON.parse('{"title":"LV030-G722简介","description":null,"frontmatter":{"title":"LV030-G722简介","date":"2025-12-25T09:11:25.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/acodec/encode/126b1b13ec35145f6e2dc684","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-12-25T09:11:25.325Z","fulluuid":"f6e2dc68452247e6aac5ee46dacf9c64","useduuid":"f6e2dc684"}},"headers":[],"relativePath":"sdoc/acodec/encode/126b1b13ec35145f6e2dc684.md","filePath":"sdoc/25-音频编解码/10-编码/LV030-G722简介.md","lastUpdated":1767537778000}'),i={name:"sdoc/acodec/encode/126b1b13ec35145f6e2dc684.md"};function t(d,e,c,o,r,p){return n(),s("div",null,[...e[0]||(e[0]=[l(`<h1 id="lv030-g722简介" tabindex="-1">LV030-G722简介 <a class="header-anchor" href="#lv030-g722简介" aria-label="Permalink to &quot;LV030-G722简介&quot;">​</a></h1><h2 id="一、g722-简介" tabindex="-1">一、G722 简介 <a class="header-anchor" href="#一、g722-简介" aria-label="Permalink to &quot;一、G722 简介&quot;">​</a></h2><p>G.722 是 ITU（国际电信联盟）定义的标准, 采用了重叠调制变换(MLT)算法，是使用 <strong>16kHz 采样率</strong> 的宽带语音编码。。适合应用在高质量的会议电话系统。有三个版本：</p><ul><li>G.722 (SB-ADPCM): 带宽 48,56,64kbit/s</li><li>G.722.1 (Siren7): 带宽 16,24,32kbit/s.</li><li>G.722.2 (AMR-WB): 带宽 6.6-23.85kbit/s (9 种）。</li></ul><h2 id="二、相关计算" tabindex="-1">二、相关计算 <a class="header-anchor" href="#二、相关计算" aria-label="Permalink to &quot;二、相关计算&quot;">​</a></h2><p>常用的是 G.722.1 编码库，一般默认的输入长度为 40ms，即 640 个采样点，1280Byte。现在我们音频采集的采样率为 16K，采样点为 640，位深为 16 位，G722.1 选择 16kbps 的比特率，那么就有：</p><div class="language-md vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">帧时间长度 = 原始采样点数 ÷ 原始采样率 = 640 ÷ 16,000 = 0.04秒 = 40毫秒</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">一帧的大小 =  采样点数 x 位深 = 640x(16/8) = 1280Byte</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">压缩后一帧字节大小 = (比特率 × 帧时间长度) ÷ 8 = (16,000 × 0.04) ÷ 8 = 640 ÷ 8 = 80字节</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div>`,7)])])}const b=a(i,[["render",t]]);export{h as __pageData,b as default};
